    selectedFormType?: string | null;
    attachedForms?: Array<{ id: string; title: string; description?: string }>;
    completedFormIds?: string[];
    settings?: {
        showReview?: boolean;
        showSocial?: boolean;
        showFeedback?: boolean;
        showRewards?: boolean;
        reviewUrl?: string;
        instagram?: string;
        twitter?: string;
        facebook?: string;
        linkedin?: string;
        socialUrl?: string;
    };
}

